# PTX source for fp16 matrix multiplication (C = A * Bᵀ)
PTX_SOURCE = r"""
.version 7.1
.target sm_80
.address_size 64

// Kernel: matmul_fp16
.visible .entry matmul_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // Thread indices
    .reg .u32 %tid_x, %tid_y;
    .reg .u32 %bid_x, %bid_y;
    .reg .u32 %row, %col;
    .reg .u32 %tile_k;
    .reg .u32 %i;

    // Pointers and offsets
    .reg .u64 %A, %B, %C;
    .reg .u64 %addr;
    .reg .u64 %temp64;
    .reg .u32 %temp32;

    // Values and accumulator
    .reg .f16 %a_val, %b_val, %c_val;
    .reg .f32 %acc;

    // Shared memory tiles (16x16)
    .shared .align 4 .b16 As[256];
    .shared .align 4 .b16 Bs[256];

    // Load kernel parameters
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // Compute thread/block indices
    mov.u32 %tid_x, %ctaid.x;
    mov.u32 %tid_y, %ctaid.y;
    mov.u32 %bid_x, %tid.x;
    mov.u32 %bid_y, %tid.y;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;

    // Global row and column this thread will compute
    mul.lo.u32 %row, %bid_y, 16;
    add.u32 %row, %row, %tid_y;
    mul.lo.u32 %col, %bid_x, 16;
    add.u32 %col, %col, %tid_x;

    // Guard against out‑of‑bounds threads
    setp.ge.u32 %p0, %row, %M;
    setp.ge.u32 %p1, %col, %N;
    @%p0 bra DONE;
    @%p1 bra DONE;

    // Initialise accumulator in FP32
    mov.f32 %acc, 0f00000000;

    // Loop over K dimension in steps of 16
    mov.u32 %tile_k, 0;
LOOP_K:
    setp.ge.u32 %p2, %tile_k, %K;
    @%p2 bra END_LOOP_K;

    // ---- Load A tile into shared memory ----
    // Compute global index for A: (row, tile_k + tid_x)
    mul.lo.u32 %temp32, %row, %K;
    add.u32 %temp32, %temp32, %tile_k;
    add.u32 %temp32, %temp32, %tid_x;          // column index
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;               // * sizeof(half)
    add.u64 %addr, %A, %temp64;
    ld.global.f16 %a_val, [%addr];

    // Store into shared As[tid_y*16 + tid_x]
    mul.lo.u32 %temp32, %tid_y, 16;
    add.u32 %temp32, %temp32, %tid_x;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, As, %temp64;
    st.shared.f16 [%addr], %a_val;

    // ---- Load B tile into shared memory ----
    // B is (N, K); we need element (col, tile_k + tid_x)
    mul.lo.u32 %temp32, %col, %K;
    add.u32 %temp32, %temp32, %tile_k;
    add.u32 %temp32, %temp32, %tid_x;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, %B, %temp64;
    ld.global.f16 %b_val, [%addr];

    // Store into shared Bs[tid_y*16 + tid_x]
    mul.lo.u32 %temp32, %tid_y, 16;
    add.u32 %temp32, %temp32, %tid_x;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, Bs, %temp64;
    st.shared.f16 [%addr], %b_val;

    // Synchronise after loading tiles
    bar.sync 0;

    // ---- Compute partial products ----
    mov.u32 %i, 0;
MUL_LOOP:
    setp.ge.u32 %p3, %i, 16;
    @%p3 bra END_MUL_LOOP;

    // Load a = As[tid_y*16 + i]
    mul.lo.u32 %temp32, %tid_y, 16;
    add.u32 %temp32, %temp32, %i;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, As, %temp64;
    ld.shared.f16 %a_val, [%addr];

    // Load b = Bs[i*16 + tid_x]
    mul.lo.u32 %temp32, %i, 16;
    add.u32 %temp32, %temp32, %tid_x;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, Bs, %temp64;
    ld.shared.f16 %b_val, [%addr];

    // Convert to FP32 and accumulate
    cvt.f32.f16 %f32_a, %a_val;
    cvt.f32.f16 %f32_b, %b_val;
    fma.rn.f32 %acc, %f32_a, %f32_b, %acc;

    add.u32 %i, %i, 1;
    bra MUL_LOOP;
END_MUL_LOOP:

    // Synchronise before next tile
    bar.sync 0;

    // Advance tile_k
    add.u32 %tile_k, %tile_k, 16;
    bra LOOP_K;
END_LOOP_K:

    // ---- Write result back to global memory ----
    // Convert accumulator to half (round‑to‑nearest)
    cvt.rn.f16.f32 %c_val, %acc;

    // Compute output address: C[row, col]
    mul.lo.u32 %temp32, %row, %N;
    add.u32 %temp32, %temp32, %col;
    cvt.u64.u32 %temp64, %temp32;
    shl.b64 %temp64, %temp64, 1;
    add.u64 %addr, %C, %temp64;
    st.global.f16 [%addr], %c_val;

DONE:
    ret;
}
"""

# ----------------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load the PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: (M, K) fp16 tensor
        B: (N, K) fp16 tensor   (will be treated as transposed)
        Returns:
            C: (M, N) fp16 tensor
        """
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        N, K2 = B.shape
        assert K == K2

        # Allocate output tensor
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # Grid and block dimensions (16x16 tiles)
        block = (16, 16, 1)
        grid = ((N + 15) // 16, (M + 15) // 16, 1)

        # Launch arguments: pointers and sizes
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            N,
            K
        ]

        # Launch the kernel
        ptx_launch(self.module, "matmul_fp16", grid, block, args)

        return C
